'use strict';
const $=s=>document.querySelector(s),KEY='genevieve-four-lessons-v2',STEPS=['看字聽讀','抄寫兩次','遮字聽寫','自己核對'];
let lessonIndex=0,index=0,step=0,mode='practice',marks={},storageOK=true,activeAudio=null;
try{const s=JSON.parse(localStorage.getItem(KEY)||'{}');marks=s.marks&&typeof s.marks==='object'?s.marks:{};lessonIndex=Number.isInteger(s.lesson)&&s.lesson>=0&&s.lesson<4?s.lesson:0;if(!localStorage.getItem(KEY)){const old=JSON.parse(localStorage.getItem('genevieve-words-A-v1')||'{}');['A1','A2','A3','A6','A7','A8'].forEach((id,i)=>{if(['known','again'].includes(old.marks?.['A'+(i+1)]))marks[id]=old.marks['A'+(i+1)];});}}catch{storageOK=false;}
const current=()=>LESSONS[lessonIndex];
function save(){try{localStorage.setItem(KEY,JSON.stringify({lesson:lessonIndex,marks}));}catch{storageOK=false;}$('#saved').textContent=storageOK?'進度只儲存在這部裝置':'瀏覽器未能保存進度，仍可繼續練習';}
function stopAudio(){if(activeAudio){activeAudio.onended=null;activeAudio.onerror=null;activeAudio.pause();activeAudio=null;}}
function renderTopics(){const nav=$('#topics');nav.replaceChildren();LESSONS.forEach((l,i)=>{const b=document.createElement('button');b.className='topic'+(i===lessonIndex?' selected':'');b.setAttribute('aria-pressed',String(i===lessonIndex));const hidden=auto.hiddenAnswers||(mode==='practice'&&step===2);const count=l.words.filter(w=>marks[w.id]==='known').length;b.innerHTML=`<span class="topicCount">${l.words.length} 項字詞 · ${count} 項已掌握</span><b>${l.title}</b><span class="sample">${hidden?'聽寫進行中，字詞已遮住':l.words.slice(0,3).map(w=>w.word).join(' · ')}</span><small>${l.code}1–${l.code}${l.words.length} · 對應工作紙</small>`;b.onclick=()=>selectLesson(i);nav.append(b);});}
function selectLesson(i){endAuto();lessonIndex=i;index=0;step=0;render();}
function render(){stopAudio();const l=current(),w=l.words[index],hide=step===2;renderTopics();$('#lessonTitle').textContent=l.title+' · '+l.words.length+' 項字詞';$('#worksheet').href=l.worksheet;$('#worksheet').textContent='↓ '+l.title+'工作紙（2 頁）';$('#practice').hidden=mode!=='practice';$('#dictation').hidden=mode!=='dictation';$('#practiceMode').classList.toggle('selected',mode==='practice');$('#dictationMode').classList.toggle('selected',mode==='dictation');$('#practiceMode').setAttribute('aria-pressed',String(mode==='practice'));$('#dictationMode').setAttribute('aria-pressed',String(mode==='dictation'));
$('#qid').textContent=w.id;$('#phase').textContent=STEPS[step];$('#pinyin').textContent=hide?'':w.pinyin;$('#word').textContent=hide?'聽一聽':w.word;$('#meaning').textContent=hide?'先聽讀音，寫完再核對。':w.meaning;$('#audioStatus').textContent='撳播放，可以再聽一次。';$('#location').textContent=w.id+'｜'+(step<2?'第 1 頁：抄寫':'第 2 頁：默書');$('#instruction').textContent=['先看示範字，聽完跟讀。','在相同題號，把完整字詞抄兩次，每格一個字。','將第 1 頁放到背面，聽錄音，在第 2 頁相同題號寫字。','看看答案，再核對紙上每一個字。'][step];$('#marking').hidden=step!==3;$('#next').textContent=step<3?['去抄寫 →','去聽寫 →','寫好喇，核對 →'][step]:index===l.words.length-1?'完成本課 ✓':'下一題 →';$('#previous').disabled=index===0;$('#counter').textContent=l.title+' · '+(index+1)+' / '+l.words.length+' 題';$('#done').hidden=true;document.querySelectorAll('[data-step]').forEach(b=>{b.classList.toggle('active',Number(b.dataset.step)===step);b.setAttribute('aria-current',Number(b.dataset.step)===step?'step':'false');});const nav=$('#wordnav');nav.replaceChildren();l.words.forEach((item,i)=>{const b=document.createElement('button');b.className=i===index?'active':'';b.setAttribute('aria-label','轉到 '+item.id);b.innerHTML=`<span class="num">${item.id}</span><span>${hide?'第 '+(i+1)+' 題':item.word}</span><span class="badge">${marks[item.id]==='known'?'✓':marks[item.id]==='again'?'↺':'·'}</span>`;b.onclick=()=>{index=i;render();};nav.append(b);});const count=l.words.filter(w=>marks[w.id]==='known').length;$('#progressLabel').textContent=count+' / '+l.words.length+' 項已掌握';$('#progress').style.width=count/l.words.length*100+'%';save();renderAuto();}
function play(slow=false){stopAudio();const a=new Audio(current().words[index].audio);activeAudio=a;a.playbackRate=slow?.75:1;a.preservesPitch=true;$('#audioStatus').textContent='正在播放普通話…';a.onended=()=>{$('#audioStatus').textContent='聽完喇。可以再聽一次。';};a.onerror=()=>{$('#audioStatus').textContent='音檔未能播放，請檢查連線後重試。';};a.play().catch(()=>{$('#audioStatus').textContent='未能播放，請再撳一次，並檢查媒體音量。';});}
// State machine: read -> wait 10 s -> read -> wait 10 s -> read -> wait 20 s -> next.
const auto={running:false,paused:false,phase:'idle',pos:0,repeat:0,deadline:0,remaining:0,hiddenAnswers:false,error:''};let timer=null;
function clearTimer(){if(timer!==null){clearInterval(timer);timer=null;}}
function endAuto(){clearTimer();stopAudio();Object.assign(auto,{running:false,paused:false,phase:'idle',pos:0,repeat:0,remaining:0,hiddenAnswers:false,error:''});$('#autoAnswers').hidden=true;$('#showAnswers').hidden=true;}
function autoFail(){clearTimer();auto.phase='error';auto.paused=true;auto.error='音檔未能播放。請檢查連線，再撳「繼續」重試。';stopAudio();renderAuto();}
function readAuto(){if(!auto.running||auto.paused)return;auto.phase='reading';auto.error='';stopAudio();const a=new Audio(current().words[auto.pos].audio);activeAudio=a;a.onended=()=>{if(activeAudio!==a||!auto.running)return;activeAudio=null;auto.phase='waiting';auto.remaining=(auto.repeat===3?20:10)*1000;auto.deadline=Date.now()+auto.remaining;renderAuto();};a.onerror=autoFail;renderAuto();a.play().catch(()=>{if(activeAudio===a)autoFail();});}
function tick(){if(!auto.running||auto.paused||auto.phase!=='waiting')return;auto.remaining=Math.max(0,auto.deadline-Date.now());if(auto.remaining===0){if(auto.repeat<3){auto.repeat++;readAuto();}else if(auto.pos<current().words.length-1){auto.pos++;auto.repeat=1;readAuto();}else{clearTimer();auto.running=false;auto.phase='complete';renderAuto();}}else renderAuto();}
function armTimer(){clearTimer();timer=setInterval(tick,200);}
function startAuto(){endAuto();Object.assign(auto,{running:true,hiddenAnswers:true,repeat:1});renderTopics();armTimer();readAuto();}
function togglePause(){if(!auto.running)return;if(!auto.paused){if(auto.phase==='waiting')auto.remaining=Math.max(0,auto.deadline-Date.now());auto.paused=true;clearTimer();activeAudio?.pause();}else{auto.paused=false;auto.error='';armTimer();if(auto.phase==='waiting')auto.deadline=Date.now()+auto.remaining;else if(auto.phase==='reading'&&activeAudio)activeAudio.play().catch(autoFail);else readAuto();}renderAuto();}
function renderAuto(){const l=current();$('#autoQuestion').textContent=auto.phase==='idle'?l.title+' · '+l.code+'1–'+l.code+l.words.length:l.title+' · '+l.words[auto.pos].id+' · 第 '+(auto.pos+1)+' / '+l.words.length+' 題';$('#autoRepeat').textContent=auto.phase==='idle'?'準備好就開始':auto.phase==='complete'?'本課默書完成':'本題第 '+auto.repeat+' / 3 次';$('#countdown').textContent=auto.paused?'已暫停':auto.phase==='reading'?'聽一聽':auto.phase==='waiting'?Math.ceil(auto.remaining/1000)+' 秒':auto.phase==='complete'?'完成 ✓':'準備';$('#autoStatus').textContent=auto.error||(auto.paused?'已保留目前進度，撳「繼續」接住做。':auto.phase==='reading'?'正在讀普通話，請在相同題號寫字。':auto.phase==='waiting'?(auto.repeat===3?(auto.pos===l.words.length-1?'留時間寫好最後一題。':'慢慢寫，倒數後讀下一個詞。'):'慢慢寫，倒數後再讀同一個詞。'):auto.phase==='complete'?'全部讀完喇！寫好就顯示答案，自己核對。':'請將抄寫頁放到背面，只看默書頁。');$('#autoPause').disabled=!auto.running;$('#autoPause').textContent=auto.paused?'繼續':'暫停';$('#autoRepeatButton').disabled=!auto.running;$('#autoStop').disabled=!auto.running;$('#autoStart').disabled=auto.running;$('#autoStart').textContent=auto.phase==='idle'?'▶ 開始本課默書':'▶ 重新開始本課';$('#showAnswers').hidden=auto.phase!=='complete';}
$('#autoStart').onclick=startAuto;$('#autoPause').onclick=togglePause;$('#autoStop').onclick=()=>{endAuto();render();};$('#autoRepeatButton').onclick=()=>{clearTimer();stopAudio();auto.repeat=1;auto.paused=false;auto.error='';armTimer();readAuto();};$('#showAnswers').onclick=()=>{auto.hiddenAnswers=false;renderTopics();$('#autoAnswers').hidden=false;$('#autoAnswers').replaceChildren(...current().words.map(w=>{const d=document.createElement('div');const s=document.createElement('small');s.textContent=w.id;d.append(s,document.createTextNode(w.word));return d;}));$('#showAnswers').hidden=true;};
$('#practiceMode').onclick=()=>{endAuto();mode='practice';render();};$('#dictationMode').onclick=()=>{endAuto();mode='dictation';render();};$('#play').onclick=()=>play();$('#slow').onclick=()=>play(true);$('#word').onclick=()=>play();document.querySelectorAll('[data-step]').forEach(b=>b.onclick=()=>{step=Number(b.dataset.step);render();});$('#previous').onclick=()=>{if(index>0){index--;step=0;render();}};$('#next').onclick=()=>{if(step<3){step++;render();}else if(index<current().words.length-1){index++;step=0;render();}else{$('#done').hidden=false;}};function mark(value){marks[current().words[index].id]=value;render();$('#audioStatus').textContent=value==='known'?'已記低：我識寫喇。':'已記低：再練一次。';}$('#known').onclick=()=>mark('known');$('#again').onclick=()=>mark('again');$('#reviewButton').onclick=()=>{const i=current().words.findIndex(w=>marks[w.id]==='again');if(i>=0){index=i;step=0;render();}else $('#audioStatus').textContent='本課未有標記「再練」的字。';};$('#reset').onclick=()=>{if(confirm('清除四課的學習進度？')){endAuto();marks={};index=0;step=0;render();}};document.addEventListener('visibilitychange',()=>{if(document.hidden){if(auto.running&&!auto.paused)togglePause();else if(!auto.running)stopAudio();}});render();
